function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(35000)});let d;try{d=await r.json()}catch{throw Error('Servizio non disponibile in questa anteprima.')};if(!r.ok){const error=Error(d.error||'Richiesta non riuscita.');error.status=r.status;throw error;}if(body&&['posts','delete','profile'].includes(path)){network.invalidate();fitcheck.invalidate();atlas.invalidateReports()}if(body&&path==='hail/end'){network.invalidate();hail.invalidate()}if(body&&path==='link'){feedLoaded=false;network.invalidate();if(body.kind==='block')atlas.invalidateReports();}return d}
const linked=(kind,target)=>feed.links.some(l=>l.kind===kind&&l.target===target);
