function modal(title,body,fn){$('#confirm-dialog').disabled=false;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog-error').textContent='';$('#confirm-dialog').hidden=!fn;$('#confirm-dialog').textContent='Salva';$('#dialog-form').onsubmit=async e=>{e.preventDefault();if(!fn)return;const b=$('#confirm-dialog');b.disabled=true;try{if(await fn()!==false)$('#dialog').close()}catch(e){$('#dialog-error').textContent=e.message}finally{b.disabled=false}};$('#dialog').showModal()}
$('#cancel-dialog').onclick=()=>$('#dialog').close();
function description(c){if(c===0)return 'Cielo sereno';if(c===1)return 'Prevalentemente sereno';if(c===2)return 'Parzialmente nuvoloso';if(c===3)return 'Nuvoloso';if([45,48].includes(c))return 'Nebbia';if(c<=57)return 'Pioviggine';if(c<=67)return 'Pioggia';if(c<=77)return 'Neve';if(c<=82)return 'Rovesci di pioggia';if(c<=86)return 'Rovesci di neve';return 'Temporali'}
function weatherHTML(){if(weatherError)return `<section class="card"><h2>Meteo non disponibile</h2><p>La fonte non ha risposto. Riprova senza perdere la località scelta.</p><button data-refresh-weather>Riprova</button></section>`;if(!weather)return '<section class="card" role="status"><h2>Caricamento del meteo…</h2><p>Stiamo consultando Open-Meteo.</p></section>';const c=weather.current;return `<section class="card weather"><div class="row"><b>ADESSO · ${esc(place.name)}</b><span class="tag">Previsione da modello</span></div><div class="temperature">${Math.round(c.temperature_2m)}°<small>${description(c.weather_code)}</small></div><div class="metrics"><div>Percepiti<b>${Math.round(c.apparent_temperature)} °C</b></div><div>Vento<b>${c.wind_speed_10m} km/h</b></div><div>Umidità<b>${c.relative_humidity_2m}%</b></div></div><p class="small">Ora del dato: ${esc(c.time.replace('T',' '))} · ${esc(weather.timezone)}</p></section>${forecastReceipt(weather)}<p class="small">Fonte: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>. Le condizioni sono stime meteorologiche, non osservazioni della community.</p>`}
function hoursHTML(){if(!weather?.hourly)return '';const h=weather.hourly;let start=h.time.findIndex(t=>t>=weather.current.time);if(start<0)start=0;return `<section class="card"><h2>Le prossime ore</h2><div class="hours">${h.time.slice(start,start+4).map((t,i)=>`<div><small>${esc(t.slice(11))}</small><b>${Math.round(h.temperature_2m[start+i])}°</b><small>${h.precipitation_probability[start+i]??'—'}% pioggia</small></div>`).join('')}</div><p class="small">Orari della località selezionata.</p></section>`}
async function loadWeather(){const seq=++weatherRequest;weather=recallWeather(place);weatherError=false;refreshWeather();const cached=await savedWeather(place);if(seq!==weatherRequest)return;if(!weather&&cached){weather=cached;refreshWeather()}try{const r=await fetch('/api/forecast?'+new URLSearchParams({lat:place.latitude,lon:place.longitude}),{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const d=await r.json();if(!Number.isFinite(d.current?.temperature_2m)||!Number.isFinite(d.current?.weather_code))throw Error();if(seq===weatherRequest){weather=d;rememberWeather(place,weather);saveWeather(place,weather)}}catch{if(seq===weatherRequest){weatherError=!weather;if(weather)weather._offline=true}}finally{if(seq===weatherRequest){refreshWeather();if(route()==='tendenze')render();else network.refreshWeather()}}}
function refreshWeather(){let notice=document.querySelector('#offline-weather');if(!notice){notice=document.createElement('p');notice.id='offline-weather';notice.className='sky-success';notice.setAttribute('role','status');document.querySelector('#main')?.before(notice)}notice.hidden=!weather?._offline;notice.textContent=weather?._offline?'Ultimo meteo salvato: '+new Date(weather._loadedAt).toLocaleString('it-IT')+'. Aggiornamento non disponibile.':'';applySkyTheme(weather);sky.refresh();living.refreshWeather();atmosphere.refresh();lente.refreshWeather();editorial.refresh();studio.refresh();nearby.refresh();atlas.refresh();social.refresh();if($('#weather-slot'))$('#weather-slot').innerHTML=weatherHTML();if($('#hours-slot'))$('#hours-slot').innerHTML=hoursHTML();document.querySelectorAll('[data-refresh-weather]').forEach(b=>b.onclick=loadWeather)}
function home(){return dailyQuestion.slot()+atmosphere.home()}
function searchForm(){return `<form id="place-search" class="card"><label for="place-query"><b>Cerca una città</b></label><div class="search-row"><input id="place-query" required minlength="2" maxlength="100" value="${esc(place.name)}" placeholder="Es. Roma, Tokyo, Buenos Aires"><button class="button">Cerca</button></div><div class="results" id="place-results" role="status"></div></form>`}
function mapView(){return `<span class="eyebrow">MAPPA E METEO</span><h1>La zona, vista da vicino.</h1><p>Scegli una città. Guarda le strade e consulta il suo meteo.</p>${searchForm()}<section class="card"><h2>${esc(place.name)}</h2><div class="map-frame" id="map-frame"><div><p>Carica la mappa interattiva di Google.</p><button id="load-map">Mostra Google Maps</button><p class="small">Il contenuto viene caricato da Google.</p></div></div><div class="actions"><a class="button" target="_blank" rel="noopener" href="${mapsURL()}">Apri Google Maps ↗</a><a class="button" target="_blank" rel="noopener" href="${mapsURL('dir')}">Indicazioni ↗</a></div><p class="small">Spostare la mappa Google non cambia il meteo: usa la ricerca città per scegliere un’altra località.</p></section><div id="weather-slot">${weatherHTML()}</div><button class="button wide" id="zone-community">Community di ${esc(place.name)}</button>`}
function worldView(){return `<span class="eyebrow">IL MONDO, A PORTATA DI MANO</span><h1>Scegli un punto sulla Terra.</h1><p>Trascina per ruotare. Clicca sul pianeta per selezionare una zona.</p><div class="globe-wrap" id="globe"><p class="globe-status" role="status">Caricamento del pianeta 3D…</p></div><div class="globe-controls"><button id="globe-in" aria-label="Ingrandisci pianeta">＋ Zoom</button><button id="globe-out" aria-label="Riduci pianeta">− Zoom</button><button id="globe-reset">Vista iniziale</button></div><div class="continents">${['Europa','Africa','Asia','Nord America','Sud America','Oceania','Antartide'].map((c,i)=>`<button data-continent="${i}">${c}</button>`).join('')}</div><section class="card globe-selection" id="globe-selection"><h2>${esc(place.name)}</h2><p>Puoi scegliere un continente o cercare direttamente una città.</p><a class="button" href="#mappa">Vedi zona e meteo</a></section><p class="small">Geografia: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth · coste vettoriali</a>. La superficie è geografica, non mostra nuvole o meteo in diretta.</p>${searchForm()}`}
async function loadFeed(more=false){if(feedBusy)return;feedBusy=true;feedError='';try{const before=more?Math.min(...feed.posts.map(p=>p.created)):0;const d=await api('posts'+(before?'?before='+before:''));feed=more?{...d,posts:[...feed.posts,...d.posts],comments:[...feed.comments,...d.comments]}:d;feedLoaded=true}catch(e){feedError=e.message}finally{feedBusy=false;if(route()==='profilo')render();else if(['pubblica','segnala'].includes(route()))refreshFeed()}}
function postCard(p){const cs=feed.comments.filter(c=>c.post===p.id),own=me?.id===p.author;return `<article class="card"><div class="post-head"><div class="avatar media-brand-mark" aria-hidden="true">${esc(p.name[0])}</div><div class="post-author"><b>${esc(p.name)}</b><span class="meta">${esc(p.city)} · ${new Date(p.created).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</span></div>${!own?`<button class="follow" data-link="follow" data-target="${p.author}" aria-pressed="${linked('follow',p.author)}">${linked('follow',p.author)?'Segui già':'+ Segui'}</button>`:''}</div><p class="post-text">${esc(p.text)}</p>${p.photo?`<img class="post-image" src="/api/photo/${p.id}" alt="Foto condivisa da ${esc(p.name)}: ${esc(p.text.slice(0,100))}" loading="lazy">`:''}<div class="row"><span class="tag">${esc(p.kind)}${p.expires?" · Scade alle "+new Date(p.expires).toLocaleTimeString("it-IT",{hour:"2-digit",minute:"2-digit"}):""}</span><span class="meta">Osservazione non verificata</span></div>${p.expires?`<div class="notice">${p.disputes>p.confirms?"Segnalazione contestata":"Osservazione della community"} · ${p.confirms||0} conferme · ${p.disputes||0} non conferme<div class="actions"><button data-link="confirm" data-target="${p.id}" aria-pressed="${linked("confirm",p.id)}">Confermo</button><button data-link="dispute" data-target="${p.id}" aria-pressed="${linked("dispute",p.id)}">Non confermo</button></div></div>`:""}${reactionButtons(p)}<div class="post-actions"><button data-link="like" data-target="${p.id}" aria-pressed="${linked('like',p.id)}">${linked('like',p.id)?'♥':'♡'} Utile · ${p.likes}</button><button data-comment="${p.id}">Commenti · ${cs.length}</button><button data-link="save" data-target="${p.id}" aria-pressed="${linked('save',p.id)}">${linked('save',p.id)?'Salvato':'Salva'}</button><button data-post-zone="${esc(p.city)}">Vedi zona</button></div>${cs.slice(-3).map(c=>`<div class="comment"><b>${esc(c.name)}</b><p>${esc(c.text)}</p></div>`).join('')}${cs.length>3?`<details><summary>Altri ${cs.length-3} commenti</summary>${cs.slice(0,-3).map(c=>`<div class="comment"><b>${esc(c.name)}</b><p>${esc(c.text)}</p></div>`).join('')}</details>`:''}<details class="post-more"><summary>Altre opzioni</summary><div class="actions"><button data-flag="${p.id}">Segnala</button>${own?`<button data-delete="${p.id}">Elimina il tuo post</button>`:`<button data-link="block" data-target="${p.author}">Nascondi autore</button>`}</div></details></article>`}
function feedHTML(){if(feedError)return `<section class="card error" role="alert"><h2>Non riusciamo a caricare i post</h2><p>${esc(feedError)}</p><button data-reload-feed>Riprova</button></section>`;if(!feedLoaded)return '<section class="card" role="status">Caricamento della community…</section>';const ps=feed.posts.filter(p=>!linked('block',p.author)).filter(p=>filter==='Tutti'||filter==='Nella zona'&&p.city.toLocaleLowerCase()===place.name.toLocaleLowerCase()||filter==='Seguiti'&&linked('follow',p.author)||filter==='Salvati'&&linked('save',p.id)).filter(p=>(p.text+' '+p.name+' '+p.city).toLowerCase().includes(search.toLowerCase()));return (ps.length?ps.map(postCard).join(''):`<section class="card empty"><h2>${filter==='Tutti'&&!search?'La prima conversazione può iniziare da te.':'Nessun post con questi filtri.'}</h2><p>Condividi un’osservazione oppure fai una domanda alla tua zona.</p><p><a href="#home">Consulta le previsioni aggiornate</a> · <a href="https://www.protezionecivile.gov.it/it/" target="_blank" rel="noopener">Fonti ufficiali</a></p><button id="clear-filter">Mostra tutti</button></section>`)+(feed.more?'<button class="wide" id="more-posts">Carica altri post</button>':'')}
function community(){return `<span class="eyebrow">METEO + PERSONE</span><h1>Com’è il cielo da te?</h1><p>Osservazioni, foto e domande. Una conversazione alla volta.</p>${quickReport.grid()}<details class="long-composer" ${route()==='pubblica'?'open':''}><summary>Scrivi un post più lungo</summary>${me?`<form class="card composer" id="compose"><div class="post-head"><div class="avatar media-brand-mark">${esc((me.profile?.name||'Tu')[0])}</div><div><b>${esc(me.profile?.name||'Scegli il tuo nome nel Profilo')}</b><div class="meta">Il tuo contributo sarà pubblico.</div></div></div><label class="sr-only" for="post-text">Testo del post</label><textarea id="post-text" required maxlength="1000" placeholder="Qui ha smesso di piovere. Com’è sul lungomare?">${esc(draft.text)}</textarea><div class="compose-fields"><label class="field"><span>Località</span><input id="post-city" required maxlength="80" value="${esc(draft.city)}"></label>${COMMUNITY_FEATURES.postType?`<label class="field"><span>Tipo di post</span><select id="post-kind">${['Osservazione','Domanda','Pioggia','Vento','Grandine','Neve','Cielo sereno','Allagamento'].map(k=>`<option ${k===draft.kind?'selected':''}>${k}</option>`).join('')}</select></label>`:''}</div><label class="field"><span>Aggiungi una foto · ridimensionata automaticamente</span><input id="post-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="row"><span id="photo-status" class="small">${photo?'Foto pronta.':'Metadati EXIF e posizione GPS vengono rimossi dalla foto preparata.'}</span><button type="button" id="remove-photo">Rimuovi foto</button></div><div class="compose-footer"><span class="small">I post lunghi restano nell’archivio dei post. Le segnalazioni rapide compaiono in Adesso. Evita indirizzi privati e dati personali.</span><button class="button" id="publish-post">Pubblica</button></div><p id="compose-error" role="alert" class="error"></p></form>`:`<section class="card"><h2>Entra nella conversazione</h2><p>Puoi leggere liberamente. Per scrivere o seguire persone, accedi.</p><a class="button" href="${signIn()}" target="_top">Accedi con ChatGPT</a></section>`}</details>${COMMUNITY_FEATURES.legacyFeed?`<div class="row"><div class="filters">${['Tutti','Nella zona','Seguiti','Salvati'].map(f=>`<button data-filter="${f}" class="${filter===f?'selected':''}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><button data-reload-feed>Aggiorna</button></div><label class="sr-only" for="feed-search">Cerca nei post caricati</label><input id="feed-search" type="search" placeholder="Cerca nei post caricati" value="${esc(search)}"><p class="small">Zona selezionata: ${esc(place.name)} · I post non sono bollettini ufficiali.</p><div id="feed">${feedHTML()}</div>`:''}`}
function composePage(){return '<div class="composer-route"><div class="composer-top"><a href="#community">← Community</a>'+(COMMUNITY_FEATURES.stories?'<a href="#stories">Foto e video della zona →</a>':'')+'</div>'+community()+'</div>'}
function profile(){return `${growth.links()}${localWeather.profile()}${sky.profileHTML()}<span class="eyebrow">IL TUO SPAZIO</span><h1>La tua redazione.</h1><section class="card"><h2>Esplora MeteoSocial</h2><div class="profile-hub">${me?`<a href="#persona:${me.id}">Il tuo profilo pubblico</a>`:""}<a href="#guida">Guida rapida all’app</a><a href="#redazione">La tua redazione e gli asset</a><a href="#studio">Creator Studio</a><a href="#stanza">Storm Rooms</a><a href="#fitcheck">Fit Check · consigli sulla mappa</a><a href="#voci">Vocali della zona</a><a href="#sfide">Sfide delle città</a><a href="#clan">Meteo-Clans</a><a href="#roast">Weather Roast</a><a href="#ripari">Luoghi coperti</a><a href="#offline">Luoghi offline</a><a href="#impostazioni">Comfort e grafica</a><a href="#patto">Il nostro patto</a><a href="#servizi">Stato delle funzioni</a><a href="#informazioni">Fonti e informazioni</a></div></section><section class="card">${me?`<h2>${esc(me.profile?.name||'Come vuoi farti chiamare?')}</h2><form id="profile-form"><label class="field"><span>Nome della redazione</span><input id="profile-name" required minlength="2" maxlength="40" value="${esc(me.profile?.name||'')}"></label><button class="button">Salva nome</button><p id="profile-status" role="status"></p></form><p><a href="/signout-with-chatgpt?return_to=%2F" target="_top">Esci dall’account</a></p>`:`<h2>Unisciti alla community</h2><p>Il tuo nome pubblico è scelto da te. L’indirizzo email non compare nei post.</p><a class="button" href="${signIn()}" target="_top">Accedi con ChatGPT</a>`}</section><section class="card"><h2>Leggi come preferisci</h2><div class="actions"><button id="large-text" aria-pressed="${prefs.large}">${prefs.large?'✓ ':''}Testo grande</button><button id="contrast" aria-pressed="${prefs.contrast}">${prefs.contrast?'✓ ':''}Contrasto alto</button></div></section><section class="card"><h2>Luoghi salvati su questo dispositivo</h2>${prefs.saved.map((p,i)=>`<div class="row"><button data-saved-place="${i}">${esc(p.name)}</button><button data-remove-place="${i}">Rimuovi</button></div>`).join('')||'<p>Nessun luogo salvato.</p>'}<button id="save-place">Salva ${esc(place.name)}</button></section>${me?`<section class="card"><h2>Autori nascosti</h2>${feed.links.filter(l=>l.kind==='block').map(l=>`<button data-link="block" data-target="${l.target}">Ripristina autore ${esc(l.target.slice(0,6))}</button>`).join('')||'<p>Nessun autore nascosto.</p>'}</section>`:''}<section class="card"><h2>Invita qualcuno a provarlo</h2><p>Chi riceve il link può visitare il sito e leggere la community.</p><button data-share-app class="button">Copia il link</button></section>`}
function assistant(){return lente.page()}
function info(){return `<h1>Chiaro, anche nei limiti.</h1><section class="card"><h2>Fonti</h2><p>Meteo e ricerca città: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>. I dati sono stime da modelli e mostrano l’orario locale della zona.</p><p>Mappa interattiva: MapLibre GL e OpenFreeMap. Radar: RainViewer. Vento e temperatura: campioni del modello Open-Meteo, non osservazioni dirette.</p><p>Mappa: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a>. Radar delle precipitazioni: <a href="https://www.rainviewer.com/" target="_blank" rel="noopener">RainViewer</a>, immagini recenti con copertura variabile, non previsioni di grandine. Indicazioni: Google Maps, servizio esterno.</p></section><section class="card"><h2>Community pubblica</h2><p>Post, foto, nome scelto e commenti sono visibili ai visitatori. Accedi con ChatGPT per partecipare. I contenuti restano salvati sul servizio, mentre le bozze rimangono nella scheda del browser.</p><p>Puoi rimuovere i tuoi post, nascondere autori e inviare segnalazioni. Le segnalazioni vengono registrate per il gestore; non è garantita una revisione immediata.</p><p>Non pubblicare dati personali, contenuti offensivi o informazioni inventate. Non usare il sito per richiedere soccorso.</p></section><section class="card"><h2>Assistente IA</h2><p>${aiReady?'Il servizio IA è collegato.':'Il servizio IA non è ancora collegato.'} Quando è attivo, aiuta a leggere i dati disponibili: non certifica il tempo, la sicurezza o i post degli utenti.</p></section>`}
function radar(){return '<h1>Radar</h1><section class="card"><h2>Radar non ancora collegato</h2><p>Il globo mostra la superficie terrestre. Non è un radar delle precipitazioni.</p><a class="button" href="#mappa">Consulta il meteo della zona</a></section>'}
function shelters(){return '<h1>Ripari</h1><section class="card"><h2>Nessun riparo verificato disponibile</h2><p>Accesso, orari e disponibilità devono essere verificati prima di proporre un luogo come riparo.</p><a class="button" href="#community">Fai una domanda alla community</a></section>'}
function render(){dailyQuestion.stop();lente.sync();document.documentElement.classList.toggle('lente-view',route()==='assistente');const openPanels=[...document.querySelectorAll('.pulse-discovery[open],.network-filter-drawer[open],.network-discovery[open]')].map(e=>e.className);sky.stop();mappaEventi.dispose();living.dispose();fitcheck.dispose();studio.dispose(route());editorial.dispose(route());nearby.dispose();atlas.dispose();atmosphere.dispose(route());network.disposeView();sensory.disposeView();experience.disposeView();social.dispose();disposeGlobe?.();disposeGlobe=null;const r=route(),isNetwork=['archivio','stories'].includes(r)||(!LIVING_FEATURES.enabled&&r==='community')||r.startsWith('persona:')||r.startsWith('post:');document.documentElement.classList.toggle('atlas-light',(['google3d','grandine-mappa','grandine','clash','testimonianza','assistente','home','mondo','mappa','mappa-classica','radar','tendenze','guida','ripari','sfide','fitcheck','avatar','studio','redazione','stanza','pubblica','segnala','profilo'].includes(r)||isNetwork));document.documentElement.classList.toggle('local-map-view',r==='mappa');document.documentElement.classList.toggle('mappa-eventi-view',r==='mappa-eventi');$('#main').dataset.page=r;$('#main').innerHTML=(isNetwork?network.page:({home,'mappa-eventi':()=>mappaEventi.page(),patto:pactPage,insieme:()=>growth.page(),evento:()=>growth.eventPage(),moderazione:()=>moderation.page(),regole:communityRules,fitcheck:()=>fitcheck.page(),roast:()=>social.home(),impostazioni:()=>experience.settings()+sensory.status(),offline:()=>sensory.offlinePage(),servizi:()=>experience.services(),clan:()=>globalFeatures.clanPage(),avatar:()=>editorial.hub(),redazione:()=>editorial.hub(),studio:()=>studio.page(),stanza:()=>editorial.roomPage(),voci:()=>social.voicesPage(),'meteo-play':()=>social.editorialPage('play'),'meteo-cinema':()=>social.editorialPage('cinema'),clash:()=>atmosphere.clash(),testimonianza:()=>atmosphere.capturePage(),mondo:()=>LIVING_FEATURES.enabled?living.page():atlas.page(),mappa:()=>living.page(),'mappa-classica':()=>living.page(),'grandine-mappa':()=>atlas.page(),guida:()=>atlas.guide(),pubblica:composePage,community:()=>LIVING_FEATURES.enabled?sky.page():network.page(),profilo:profile,assistente:assistant,tendenze:()=>atlas.weatherPage(),informazioni:info,radar:()=>atlas.page(),ripari:()=>nearby.page(),sfide:()=>challenges.page(),segnala:composePage}[r]||home))();for(const cls of openPanels)document.querySelector('details.'+cls)?.setAttribute('open','');$('#place').textContent='⌖ '+place.name+' ⌄';document.documentElement.classList.toggle('large-text',prefs.large);document.documentElement.classList.toggle('contrast',prefs.contrast);document.querySelectorAll('nav>a').forEach(a=>{const active=a.hash==='#'+r||(r==='google3d'&&a.hash==='#mondo')||(isNetwork&&a.hash==='#community')||(['radar','grandine-mappa','mappa','mappa-classica'].includes(r)&&a.hash==='#mappa-eventi');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(!LIVING_FEATURES.vocali)document.querySelectorAll('a[href="#voci"]').forEach(a=>a.hidden=true);if(!LIVING_FEATURES.meteoClans)document.querySelectorAll('a[href="#clan"]').forEach(a=>a.hidden=true);bind();social.bind();if(!isNetwork&&!['radar','ripari'].includes(r))globalFeatures.bind();experience.bind();sensory.bind();if(isNetwork)network.bind();atlas.bind();living.bind();sky.bind();atmosphere.bind();nearby.bind();challenges.bind();editorial.bind();studio.bind();fitcheck.bind();if(r==='profilo'&&!feedLoaded&&!feedBusy)loadFeed()}
function choose(p){const keepMap=route()==='mappa';place={name:p.name,latitude:p.latitude,longitude:p.longitude,country_code:p.country_code||null,source:p.source||null,accuracy:p.accuracy||null};draft.city=p.source==='gps'?'':p.name;weather=null;weatherError=false;saveDraft();store();if(keepMap){$('#place').textContent='⌖ '+place.name+' ⌄';living.updatePlace()}else render();loadWeather();onboarding.cityPicked()}
function refreshFeed(){if($('#feed')){$('#feed').innerHTML=feedHTML();bindFeed()}}
let searchSeq=0;async function searchPlace(e){e.preventDefault();const box=$('#place-results'),query=$('#place-query').value.trim();if(query.length<2)return;const seq=++searchSeq;box.textContent='Ricerca delle località…';try{const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:query,count:'6',language:'it',format:'json'}),{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const d=await r.json();if(seq!==searchSeq)return;box.innerHTML=d.results?.length?d.results.map((p,i)=>`<button type="button" data-result="${i}">${esc([p.name,p.admin1,p.country].filter(Boolean).join(', '))}</button>`).join(''):'Nessuna città trovata. Prova il comune più vicino.';box.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{$('#dialog').close();choose(d.results[+b.dataset.result])})}catch{if(seq===searchSeq)box.textContent='Ricerca non disponibile. Riprova.'}}
async function share(){await growth.share()}
function bindFeed(){document.querySelectorAll('[data-link]').forEach(b=>b.onclick=async()=>{if(!me)return login();b.disabled=true;try{await api('link',{kind:b.dataset.link,target:b.dataset.target,active:!linked(b.dataset.link,b.dataset.target)});await loadFeed();network.invalidate();if(route()==='profilo')render()}catch(e){toast(e.message)}finally{b.disabled=false}});document.querySelectorAll('[data-comment]').forEach(b=>b.onclick=()=>{if(!me)return login();const id=b.dataset.comment,cid=crypto.randomUUID();modal('Rispondi al post',`<label class="field"><span>Commento pubblico</span><textarea id="comment-input" required maxlength="500">${esc(commentDrafts[id]||'')}</textarea></label>`,async()=>{const text=$('#comment-input').value.trim();if(!text)return false;await api('comments',{id:cid,post:id,text});delete commentDrafts[id];await loadFeed()});$('#comment-input').oninput=e=>commentDrafts[id]=e.target.value});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>modal('Eliminare il tuo post?','<p>Il post non sarà più visibile nella community.</p>',async()=>{await api('delete',{id:b.dataset.delete});await loadFeed()}));document.querySelectorAll('[data-flag]').forEach(b=>b.onclick=()=>{if(!me)return login();modal('Segnala al gestore','<label class="field"><span>Motivo</span><select id="flag-reason"><option>Informazione falsa o fuorviante</option><option>Offese o spam</option><option>Dati personali</option><option>Contenuto pericoloso</option></select></label><p class="small">La richiesta viene registrata. Non è un canale di emergenza.</p>',async()=>{await api('flag',{post:b.dataset.flag,reason:$('#flag-reason').value});toast('Segnalazione registrata per il gestore.')})});document.querySelectorAll('[data-post-zone]').forEach(b=>b.onclick=()=>{location.hash='mappa';setTimeout(()=>{if($('#place-query')){$('#place-query').value=b.dataset.postZone;$('#place-search').requestSubmit()}},0)});$('#clear-filter')?.addEventListener('click',()=>{filter='Tutti';search='';render()});$('#more-posts')?.addEventListener('click',()=>loadFeed(true));document.querySelectorAll('[data-reload-feed]').forEach(b=>b.onclick=()=>loadFeed())}
function bind(){if(route()==='mappa-eventi')mappaEventi.bind();dailyQuestion.bind();if(route()==='home'&&!document.querySelector('[data-human-weather]'))document.querySelector('#main').insertAdjacentHTML('beforeend',growth.humanSlot()+growth.links());growth.bind();if(['home','mondo','tendenze'].includes(route())&&!document.querySelector('[data-local-weather]')){const anchor=document.querySelector('#living-title')||document.querySelector('#atmo-rain')||document.querySelector('#main').firstElementChild;anchor?.insertAdjacentHTML('beforebegin',localWeather.slot())}localWeather.bind();moderation.bind();sky.bindProfile();bindExtras();bindFeed();document.querySelectorAll('[data-search-place]').forEach(b=>b.onclick=()=>location.hash='mappa');document.querySelectorAll('[data-refresh-weather]').forEach(b=>b.onclick=loadWeather);$('#place-search')?.addEventListener('submit',searchPlace);$('#load-map')?.addEventListener('click',()=>{$('#map-frame').innerHTML=`<iframe title="Google Maps di ${esc(place.name)}" src="https://maps.google.com/maps?q=${encodeURIComponent(place.latitude+','+place.longitude)}&z=13&output=embed" allowfullscreen loading="lazy"></iframe>`});$('#zone-community')?.addEventListener('click',()=>{network.showCity(place.name);location.hash='community'});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#feed-search')?.addEventListener('input',e=>{search=e.target.value;refreshFeed()});$('#post-text')?.addEventListener('input',e=>{draft.text=e.target.value;saveDraft()});$('#post-city')?.addEventListener('input',e=>{draft.city=e.target.value;saveDraft()});$('#post-kind')?.addEventListener('change',e=>{draft.kind=e.target.value;saveDraft()});$('#remove-photo')?.addEventListener('click',()=>{photo='';$('#post-photo').value='';$('#publish-post').disabled=false;$('#photo-status').textContent='Foto rimossa.'});$('#post-photo')?.addEventListener('change',async e=>{photo='';const input=e.target,f=input.files?.[0],button=$('#publish-post');if(!f){button.disabled=false;$('#photo-status').textContent='Nessuna foto selezionata.';return;}button.disabled=true;$('#photo-status').textContent='Preparo la foto…';try{const prepared=await fotoDataURL(f);if(!input.isConnected||input.files?.[0]!==f)return;photo=prepared;$('#photo-status').textContent='Foto pronta. Metadati EXIF e posizione GPS rimossi.'}catch(error){if(input.isConnected&&input.files?.[0]===f)$('#photo-status').textContent=error.message}finally{if(input.isConnected&&input.files?.[0]===f)button.disabled=false}});
$('#compose')?.addEventListener('submit',async e=>{e.preventDefault();const b=$('#publish-post');b.disabled=true;$('#compose-error').textContent='';try{await api('posts',{id:postId,text:draft.text,city:draft.city,kind:COMMUNITY_FEATURES.postType?draft.kind:'Osservazione',photo});postId=crypto.randomUUID();draft.text='';photo='';saveDraft();location.hash='community';render();toast('Post pubblicato nella community.')}catch(e){if($('#compose-error'))$('#compose-error').textContent=e.message}finally{b.disabled=false}});
$('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('profile',{name:$('#profile-name').value});me=await api('me');social.onIdentity();render();toast('Nome aggiornato.')}catch(e){$('#profile-status').textContent=e.message}});$('#large-text')?.addEventListener('click',()=>{prefs.large=!prefs.large;store();render()});$('#contrast')?.addEventListener('click',()=>{prefs.contrast=!prefs.contrast;store();render()});$('#save-place')?.addEventListener('click',()=>{if(!prefs.saved.some(p=>p.latitude===place.latitude&&p.longitude===place.longitude))prefs.saved.push({...place});store();render()});document.querySelectorAll('[data-remove-place]').forEach(b=>b.onclick=()=>{prefs.saved.splice(+b.dataset.removePlace,1);store();render()});document.querySelectorAll('[data-saved-place]').forEach(b=>b.onclick=()=>{choose(prefs.saved[+b.dataset.savedPlace]);location.hash='home'});document.querySelectorAll('[data-share-app]').forEach(b=>b.onclick=share);}

const pwaDayPlan=preparePwaShortcut();
installUIFeedback();
installFeatureVisibility();
$('#place').onclick=()=>{modal('Scegli la città','<label for="place-query">Città<input id="place-query" minlength="2" placeholder="Cerca una città" required></label><button type="submit">Cerca</button><div id="place-results" role="status"></div>',null);$('#dialog-form').onsubmit=searchPlace};$('#share-app').onclick=share;window.addEventListener('hashchange',()=>{searchSeq++;render();$('#main').focus({preventScroll:true});window.scrollTo(0,0)});render();growth.restoreZone();growth.morning();if(new URL(location.href).searchParams.get('action')==='segnala')sky.open();if(pwaDayPlan)focusPwaDayPlan();loadWeather();api('me').then(d=>{me=d.id?d:null;aiReady=d.ai;google3dReady=d.google3d===true;if(route()!=='mappa')render();social.onIdentity()}).catch(()=>{apiAvailable=false});

function trends(){if(!weather)return `<h1>Tendenze</h1><div id="weather-slot">${weatherHTML()}</div>`;const d=weather.daily;if(!d)return '<h1>Tendenze non disponibili</h1>';return `<span class="eyebrow">IL METEO IN 30 SECONDI</span><h1>La giornata. La settimana.</h1><p>${esc(place.name)} · Riepilogo automatico dai dati Open-Meteo.</p><div class="trend-stories"><article class="trend-story"><span>01 / OGGI</span><h2>${description(d.weather_code[0])}</h2><p>Da ${Math.round(d.temperature_2m_min[0])}° a ${Math.round(d.temperature_2m_max[0])}°.</p></article><article class="trend-story"><span>02 / PIOGGIA</span><h2>${d.precipitation_probability_max[0]??'—'}%</h2><p>Probabilità massima prevista oggi. Non indica quanta pioggia cadrà.</p></article><article class="trend-story"><span>03 / UV</span><h2>${d.uv_index_max[0]??'—'}</h2><p>Indice UV massimo previsto. Consulta le indicazioni sanitarie sulla protezione dal sole.</p></article></div><button class="button" id="download-trend">Scarica la card da condividere</button><p class="small">La card include località, fonte e ora del dato.</p><section class="card"><h2>I prossimi 7 giorni</h2>${d.time.map((date,i)=>`<div class="week-row"><b>${new Date(date+'T12:00:00').toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short'})}</b><span>${description(d.weather_code[i])}</span><strong>${Math.round(d.temperature_2m_min[i])}° / ${Math.round(d.temperature_2m_max[i])}°</strong><small>${d.precipitation_probability_max[i]??'—'}% pioggia</small></div>`).join('')}<p class="small">L’incertezza cresce con la distanza nel tempo. Le previsioni possono cambiare.</p></section><section class="card"><h2>Tendenze a 15–30 giorni e creator</h2><p>Non sono ancora disponibili analisi editoriali verificate o abbonamenti. Le previsioni giornaliere non vengono estese artificialmente a un mese.</p></section>`}
function bindExtras(){quickReport.bind();$('#download-trend')?.addEventListener('click',()=>{if(!weather)return;const c=document.createElement('canvas');c.width=1080;c.height=1350;const x=c.getContext('2d');x.fillStyle='#123bb2';x.fillRect(0,0,1080,1350);x.fillStyle='white';x.font='bold 56px system-ui';x.fillText('MeteoSocial',70,130);x.font='32px system-ui';x.fillText('IL METEO DIVENTA SOCIAL',70,185);x.font='bold 54px system-ui';const name=place.name.length>30?place.name.slice(0,29)+'…':place.name;x.fillText(name,70,330,940);x.font='bold 170px system-ui';x.fillText(Math.round(weather.current.temperature_2m)+'°',70,570);x.font='42px system-ui';x.fillText(description(weather.current.weather_code),70,665,940);x.font='32px system-ui';x.fillText('Previsione da modello · non un’allerta',70,765);x.fillText('Vento '+weather.current.wind_speed_10m+' km/h',70,840);x.fillText('Fonte: Open-Meteo',70,1050);x.fillText('Dato: '+weather.current.time.replace('T',' '),70,1110);x.font='25px system-ui';x.fillText(location.origin,70,1230,940);c.toBlob(blob=>{if(!blob){toast('Immagine non disponibile.');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='meteosocial-oggi.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)},'image/png')})}
setInterval(()=>{network.expire();if(!LIVING_FEATURES.enabled&&route()==='community'&&feedLoaded){feed.posts=feed.posts.filter(p=>!p.expires||p.expires>Date.now());refreshFeed()}},60000);

function reactionButtons(p){return `<div class="reaction-group" aria-label="Reazioni meteo">${[["heat","🔥","Caldo"],["snow","❄️","Neve"],["storm","⚡","Temporale"]].map(([kind,emoji,label])=>`<button data-link="${kind}" data-target="${p.id}" aria-label="${label}: ${p[kind+"_count"]||0} reazioni" aria-pressed="${linked(kind,p.id)}">${emoji} ${p[kind+"_count"]||0}</button>`).join("")}</div>`}

installUpdates();

setInterval(()=>{if(!document.hidden)loadWeather()},900000);

// The local map owns the brief opening flight; city and hours remain editable in the header and Oggi.
installOffline();

installNotificationOffer();

installForecastHistory({get:()=>({place,weather}),modal});
